/**
 * @local/yuno-avatar — 浏览器半端
 * ============================================================================
 * 给每条助手消息左边挂一个圆形头像（猫耳 + 品红描边），像聊天软件那样。
 * 纯 DOM 层的事：找到消息容器 → 打标记 → CSS 用 ::before 画头像。
 * 头像和光环都是烘焙好的圆图（四角透明），不依赖 border-radius 的裁剪，
 * 也不靠 box-shadow 打光，避免某些环境里被画成方的。
 * ============================================================================
 */
window.__ModuleLoader__.load({
  id: '@local/yuno-avatar',
  factory(require) {
    /* 头像 + 渐变描边（46px 设计，头像本体 42px） */
    const AVATAR = 'data:image/png;base64,'
    /* 外圈光环（64px 设计，播放时亮度呼吸） */
    const RING = 'data:image/png;base64,'
    /* 「详细过程」标题前的图标：千问豆乃包的 logo */
    const LOGO = 'data:image/png;base64,'

    /* 助手最终回复的容器；两个候选都试，命中哪个算哪个 */
    const SELECTORS = [
      '[data-chat-flow-kind="assistant-step"]',
      '[data-turn-process-answer]',
    ]
    const SELECTOR = SELECTORS.join(',')
    const MARK = 'yuno-av-on'
    /* 语音插件（dsh-yuno-tts）在「正在念的那条」消息上挂这个类 */
    const SPEAKING = 'yuno-av-voice'
    const STYLE_ID = 'yuno-avatar-style'

    const CSS = `
[data-chat-flow-kind="assistant-step"].${MARK},
[data-turn-process-answer].${MARK}{
  position: relative !important;
  padding-left: 54px;
  min-height: 42px;
}

/* 头像：整张图是圆的（四角透明），边缘已经烘焙好渐变描边 */
[data-chat-flow-kind="assistant-step"].${MARK}::before,
[data-turn-process-answer].${MARK}::before{
  content: '';
  position: absolute;
  left: -2px;
  top: -2px;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background-image: url("${AVATAR}");
  background-size: 100% 100%;
  background-repeat: no-repeat;
  pointer-events: none;
  z-index: 1;
  transition: filter .25s;
}

/* 外圈光环：静默时只留一点，语音播放才亮起来 */
[data-chat-flow-kind="assistant-step"].${MARK}::after,
[data-turn-process-answer].${MARK}::after{
  content: '';
  position: absolute;
  left: -11px;
  top: -11px;
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background-image: url("${RING}");
  background-size: 100% 100%;
  background-repeat: no-repeat;
  pointer-events: none;
  z-index: 0;
  opacity: .26;
  transition: opacity .3s;
  transform-origin: 50% 50%;
}

/* ---- 语音播放中：正在念的那条消息，头像亮一圈 ---- */
[data-chat-flow-kind="assistant-step"].${MARK}.${SPEAKING}::before,
[data-turn-process-answer].${MARK}.${SPEAKING}::before{
  filter:
    brightness(1.08) saturate(1.1)
    drop-shadow(0 0 5px color-mix(in srgb, var(--dsw-alias-brand-primary, #ff2d78) 60%, transparent))
    drop-shadow(0 0 12px color-mix(in srgb, var(--dsw-alias-brand-primary, #ff2d78) 34%, transparent));
}
[data-chat-flow-kind="assistant-step"].${MARK}.${SPEAKING}::after,
[data-turn-process-answer].${MARK}.${SPEAKING}::after{
  opacity: 1;
  /* 只留静态滤镜：动画只动透明度，光环边缘不动，看起来是亮度在呼吸 */
  filter: brightness(1.35) saturate(1.1);
  will-change: opacity;
  animation: yuno-av-ring 1.8s ease-in-out infinite alternate;
}
/* 亮度呼吸：不缩放，边缘不动；首尾同状态，循环点不会跳 */
@keyframes yuno-av-ring{
  0%{ opacity: 1 }
  100%{ opacity: .2 }
}
@media (prefers-reduced-motion: reduce){
  [data-chat-flow-kind="assistant-step"].${MARK}.${SPEAKING}::after,
  [data-turn-process-answer].${MARK}.${SPEAKING}::after{
    animation: none;
    opacity: 1;
    transform: none;
  }
}

/* 「思考」行前面的图标：换成千问豆乃包的 logo */
[data-variant="think"] [data-disclosure-row] [class*="iconIdle"] > svg{ display:none !important }
[data-variant="think"] [data-disclosure-row] [class*="iconIdle"]::before{
  content: '';
  display: inline-block;
  width: 14px;
  height: 14px;
  background: url("${LOGO}") center / contain no-repeat;
}
/* 「深度分析中」这个过程组标题前的图标：也换成 logo */
[data-step-process-icon] > svg{ display:none !important }
[data-step-process-icon]::before{
  content: '';
  display: inline-block;
  width: 16px;
  height: 16px;
  background: url("${LOGO}") center / contain no-repeat;
}

/* 状态行的扫光：默认蓝色，统一换成千问豆乃包的紫色 */
[class*="sweep"]{
  color: #a06bff !important;
}
`

    const hasText = (el) => {
      try {
        return (el.innerText || el.textContent || '').trim().length > 0
      } catch {
        return false
      }
    }

    /* 折叠的「详细过程」有渐隐背景，会压住头像 —— 那里不挂头像，只留给正文和最终答案 */
    const SKIP = '[data-step-process], [data-turn-process], [data-turn-process-member], [data-turn-process-hidden]'

    const markOne = (el) => {
      if (!el || el.nodeType !== 1) return
      if (el.classList.contains(MARK)) return
      if (!el.matches(SELECTOR)) return
      if (!hasText(el)) return
      try {
        if (el.closest(SKIP)) return
      } catch { /* 忽略 */ }
      el.classList.add(MARK)
    }

    const markTree = (root) => {
      if (!root || typeof root.querySelectorAll !== 'function') return
      try {
        for (const el of root.querySelectorAll(SELECTOR)) markOne(el)
      } catch { /* 忽略 */ }
      markOne(root)
    }

    function apply(ctx) {
      const doc = document
      let style = doc.getElementById(STYLE_ID)
      if (!style) {
        style = doc.createElement('style')
        style.id = STYLE_ID
        style.textContent = CSS
        doc.head.appendChild(style)
      }

      markTree(doc.body)

      const observer = new MutationObserver((records) => {
        for (const rec of records) {
          if (rec.type === 'childList') {
            for (const node of rec.addedNodes) {
              if (node.nodeType === 1) markTree(node)
            }
          } else if (rec.type === 'characterData' || rec.type === 'subtree') {
            markTree(rec.target)
          }
        }
      })
      try {
        observer.observe(doc.body, { childList: true, subtree: true, characterData: true })
      } catch { /* 忽略 */ }

      /* 流式输出时文字是慢慢长出来的：定时补标，成本很低 */
      const timer = setInterval(() => markTree(doc.body), 1500)

      const cleanup = () => {
        try { observer.disconnect() } catch { /* 忽略 */ }
        try { clearInterval(timer) } catch { /* 忽略 */ }
        try { style.remove() } catch { /* 忽略 */ }
        try {
          for (const el of doc.querySelectorAll('.' + SPEAKING)) el.classList.remove(SPEAKING)
        } catch { /* 忽略 */ }
        try {
          for (const el of doc.querySelectorAll('.' + MARK)) el.classList.remove(MARK)
        } catch { /* 忽略 */ }
      }

      if (typeof ctx.effect === 'function') ctx.effect(() => cleanup, 'yuno-avatar: 头像标记')
      return cleanup
    }

    return {
      inject: [],
      apply,
    }
  },
})